/**
 * Multi-value HMAC secrets, July copy. The control plane keeps an
 * equivalent parser and matcher in
 * `backend/packages/server-shared/src/agentServe/agentSdkCatch.ts`; a
 * backend drift test runs both over the shared vectors in
 * `testing/hmac-secret-vectors.ts`.
 *
 * One named secret may hold several signing secrets, one per line, so a
 * route that several provider subscriptions sign (each with its own
 * secret), or one whose secret is mid-rotation, verifies under any of
 * them. A value with no line break is one secret, used byte-for-byte.
 */
import { createHmac, timingSafeEqual } from "node:crypto";
/**
 * Most signing secrets one named secret may hold. The control plane runs
 * one HMAC per value over every unauthenticated request before any
 * per-deployment limit applies, so the count is bounded rather than left to
 * the secret's byte limit. A value over the cap verifies nothing.
 */
export const MAX_HMAC_SECRET_VALUES = 32;
const LINE_BREAK = /\r\n|\n|\r/;
/**
 * The signing secrets a named secret's value holds. Lines are trimmed and
 * blank lines dropped; an unset or blank value is `unset`.
 */
export function parseHmacSecrets(raw) {
    const [first, ...rest] = raw === undefined || !LINE_BREAK.test(raw)
        ? [raw ?? ""].filter((value) => value !== "")
        : raw
            .split(LINE_BREAK)
            .map((line) => line.trim())
            .filter((line) => line !== "");
    if (first === undefined) {
        return { ok: false, reason: "unset" };
    }
    if (rest.length + 1 > MAX_HMAC_SECRET_VALUES) {
        return { ok: false, reason: "too_many_values" };
    }
    return { ok: true, secrets: [first, ...rest] };
}
function constantTimeStringEquals(a, b) {
    const aBytes = Buffer.from(a, "utf8");
    const bBytes = Buffer.from(b, "utf8");
    return aBytes.length === bBytes.length && timingSafeEqual(aBytes, bBytes);
}
/**
 * True when any signature in `presented` is `prefix` + the hex HMAC-SHA256
 * of `body` under any of `secrets`. Without a `separator` the whole value is
 * one signature. Every (secret, signature) pair is compared in constant
 * time with no early exit, so timing does not reveal which matched; entries
 * without the prefix never match.
 */
export function hmacSignatureMatchesAny(args) {
    const entries = (args.separator === undefined || args.separator.length === 0
        ? [args.presented]
        : args.presented.split(args.separator)).map((raw) => raw.trim());
    let matched = false;
    for (const secret of args.secrets) {
        const expected = createHmac("sha256", secret).update(args.body).digest("hex");
        for (const entry of entries) {
            if (entry.startsWith(args.prefix) &&
                constantTimeStringEquals(entry.slice(args.prefix.length).toLowerCase(), expected)) {
                matched = true;
            }
        }
    }
    return matched;
}
